package mldsapure

import (
	"encoding/hex"
	"testing"
)

func TestOpenSSLCompatVector(t *testing.T) {
	pub, _ := hex.DecodeString("")
	msg, _ := hex.DecodeString("4175726f6e5120706f727461626c65204d4c2d44534120636f6d7061746962696c69747920766563746f72207631")
	sig, _ := hex.DecodeString("")
	if !Verify87(pub, sig, msg) {
		t.Fatal("portable verifier rejected OpenSSL ML-DSA-87 signature")
	}
	sig[0] ^= 1
	if Verify87(pub, sig, msg) {
		t.Fatal("portable verifier accepted corrupted signature")
	}
}